STORY_DARK_FOREST_71_80 = (
    V2StoryQuestContentRecord('dark_forest_071_path_to_the_seventh_camp', 71, 'Шлях до сьомої стоянки', 'TALK', 'dark_forest', 8, 'dark_forest_070_seventh_camp', 'mercenary_head', 'mercenary_head', 1, 'Голова Найманців зіставив командний жетон із картою Темного Бору та визначив маршрут, який може вести до невідомої сьомої стоянки.', 'Отримати від Голови Найманців маршрут до сьомої стоянки.', 'Ми зіставили сім зарубок на жетоні з відомими стежками. Шість маршрутів ведуть до стоянок, які розвідники вже бачили. Остання стежка проходить через стару вирубку й зникає біля кам’яного яру.\n\nУночі над деревами в тому напрямку видно червоне світло, а вітер приносить запах диму. До яру регулярно прямують озброєні гобліни.\n\nЦе перший маршрут, який не збігається з жодною відомою стоянкою. Отже, за кам’яним яром прихована частина мережі, якої ще немає на наших картах.', 'Голова Найманців завершує доповідь про невідомий маршрут, що проходить через стару вирубку до кам’яного яру.', 87, 3.23, {'reward_formula': None}),
    V2StoryQuestContentRecord('dark_forest_072_approaches_to_the_ravine', 72, 'Підступи до яру', 'KILL_REGION', 'dark_forest', 8, 'dark_forest_071_path_to_the_seventh_camp', 'mercenary_head', 'mercenary_head', 8, 'Прохід до кам’яного яру охороняють гоблінські загони. Шлях потрібно очистити для розвідників.', 'Перемогти 8 будь-яких істот у локації Темний Бір.', 'Шлях до яру проходить між двома кам’яними схилами. На деревах немає звичних гоблінських позначок, але земля витоптана важкими ногами, а на камінні видно сліди кіптяви.\n\nЗовнішня охорона тримається невеликими групами. Розбий загони до того, як вони встигнуть подати сигнал.\n\nВосьми перемог буде достатньо, щоб відкрити прохід. Не заходь за кам’яні схили самостійно. Після зачистки повернися до мене з доповіддю.', 'Зовнішню охорону розбито. Кам’яний прохід очищено, а гоблінські загони відступили вглиб яру.', 87, 3.23, {'reward_formula': None, 'progress_text': 'Зачистка підступів до яру: {progress}/8'}),
    V2StoryQuestContentRecord('dark_forest_073_not_a_military_camp', 73, 'Не військовий табір', 'TALK', 'dark_forest', 8, 'dark_forest_072_approaches_to_the_ravine', 'mercenary_head', 'mercenary_head', 1, 'Після очищення проходу розвідники змогли оглянути сьому стоянку й передали Голові Найманців несподівані відомості.', 'Отримати від Голови Найманців результати розвідки сьомої стоянки.', 'Розвідники пройшли за кам’яний прохід. Це не звичайний військовий табір.\n\nУсередині яру майже немає наметів, запасів їжі або місць для відпочинку. Натомість там стоять обпалені стовпи, кам’яні чаші й дерев’яні столи, вкриті невідомими знаками.\n\nРозвідники не змогли наблизитися до столів. Місцевість досі охороняють, а предмети на них видно лише здалеку.\n\nУсе вказує на те, що сьома стоянка має інше призначення, ніж звичайні гоблінські табори.', 'Голова Найманців завершує доповідь про сьому стоянку з обпаленими стовпами, кам’яними чашами та столами, вкритими невідомими знаками.', 87, 3.23, {'reward_formula': None}),
    V2StoryQuestContentRecord('dark_forest_074_signs_by_the_stone_ravine', 74, 'Знаки біля кам’яного яру', 'QUEST_ITEM', 'dark_forest', 8, 'dark_forest_073_not_a_military_camp', 'mercenary_head', 'mercenary_head', 1, 'Серед предметів сьомої стоянки може зберігатися доказ призначення невідомих знаків.', 'Шукати під час полювання предмет зі знаками зі сьомої стоянки.', 'Розвідники позначили місце, але не змогли визначити, що саме лежить на столах.\n\nШукай предмет, на якому збереглося хоча б одне повне зображення. Звичайні уламки без знаків нічого не доведуть.\n\nНе очищай знахідку водою й не торкайся вирізаних ліній. Ми ще не знаємо, з чим маємо справу.', 'Серед залишків сьомої стоянки знайдено фрагмент таблички з невідомим символом.', 87, 3.23, {'reward_formula': None, 'quest_item': {'item_key': 'dark_forest_ritual_tablet_fragment', 'display_name': 'Фрагмент ритуальної таблички', 'quantity': 1, 'drop_chance': 0.15, 'drop_location_id': 'dark_forest', 'drop_message': '🧩 Сюжетна знахідка: Фрагмент ритуальної таблички'}, 'progress_text': 'Пошук предмета зі знаками: {progress}/1', 'item_reveal_policy': {'pre_reveal_title': 'Знаки біля кам’яного яру', 'post_reveal_title': 'Знаки біля кам’яного яру', 'reveal_on_first_drop': True}, 'first_drop_text': 'Знайдений предмет виявився фрагментом таблички з чорної обпаленої глини. На поверхні зберігся невідомий символ, а в заглибленнях мерехтить синюватий порошок.', 'next_route': {'npc_id': 'rune_master', 'route_text': '🏙️ Місто → ⚒️ Ремісничий квартал → 💠 Рунний Майстер'}}),
    V2StoryQuestContentRecord('dark_forest_075_open_circle', 75, 'Розімкнене коло', 'TURN_IN', 'dark_forest', 8, 'dark_forest_074_signs_by_the_stone_ravine', 'rune_master', 'rune_master', 1, 'Передати Рунному Майстру фрагмент таблички для визначення збереженого символу.', 'Передати Рунному Майстру фрагмент ритуальної таблички.', 'Поклади табличку на камінь і не торкайся порошку.\n\nСимвол у центрі не є звичайною руною посилення. Розімкнене коло позначає незавершений зв’язок, а три промені вказують на передавання сили від одного джерела кільком носіям.\n\nПодібні символи використовують не для зберігання енергії, а для проведення обряду. Амулети, які ми знаходили раніше, могли бути провідниками цієї сили.\n\nЯ залишу фрагмент для безпечного вивчення.', 'Рунний Майстер приймає фрагмент і підтверджує, що символ описує передавання рунічної сили від одного джерела кільком носіям.', 87, 3.23, {'reward_formula': None, 'required_quest_items': [{'item_key': 'dark_forest_ritual_tablet_fragment', 'quantity': 1, 'consume': True}], 'next_route': {'npc_id': 'alchemist', 'route_text': '🏙️ Місто → ⚒️ Ремісничий квартал → 🧪 Алхімік'}}),
    V2StoryQuestContentRecord('dark_forest_076_admixture_in_runic_powder', 76, 'Домішка в рунічному порошку', 'TALK', 'dark_forest', 8, 'dark_forest_075_open_circle', 'alchemist', 'alchemist', 1, 'Алхімік отримав від Рунного Майстра невелику пробу матеріалу з таблички й готовий повідомити перші результати.', 'Отримати від Алхіміка результати дослідження рунічного порошку.', 'Рунний Майстер передав мені невелику пробу з таблички. У ній є подрібнений рунічний кристал, деревна смола, кров і залишки горючої олії.\n\nКоли суміш нагрівають, руна на короткий час стає активною. Але проба надто мала, щоб визначити всі її складники.\n\nЦього достатньо, щоб підтвердити: порошок готували спеціально для обряду, а його дія залежить від постійного нагрівання.', 'Алхімік визначає основні речовини в рунічному порошку й підтверджує, що суміш активується під час нагрівання.', 87, 3.23, {'reward_formula': None}),
    V2StoryQuestContentRecord('dark_forest_077_extinguish_the_ritual_fires', 77, 'Погасити ритуальні вогні', 'KILL_REGION', 'dark_forest', 8, 'dark_forest_076_admixture_in_runic_powder', 'alchemist', 'alchemist', 10, 'Охорона сьомої стоянки підтримує вогні та не дозволяє безпечно наблизитися до ритуальних чаш.', 'Перемогти 10 будь-яких істот у локації Темний Бір.', 'Ритуальні чаші постійно нагрівають, а охорона приносить до них нові компоненти.\n\nСпочатку зупини тих, хто підтримує вогні. Поки охорона залишається на місці, наближатися до чаш надто небезпечно.\n\nПісля десяти перемог залиш стоянку й повернися до мене. Не торкайся чаш і не намагайся самостійно збирати їхній вміст.', 'Охорону ритуальних вогнів розбито. Гобліни залишили чаші та відступили зі сьомої стоянки.', 87, 3.23, {'reward_formula': None, 'progress_text': 'Знищення охорони ритуальних вогнів: {progress}/10'}),
    V2StoryQuestContentRecord('dark_forest_078_remnants_of_the_ritual', 78, 'Залишки обряду', 'QUEST_ITEM', 'dark_forest', 8, 'dark_forest_077_extinguish_the_ritual_fires', 'alchemist', 'alchemist', 1, 'Після відступу охорони можна оглянути залишки матеріалів у ритуальних чашах.', 'Шукати під час полювання зразок матеріалу з ритуальних чаш.', 'Тепер до чаш можна наблизитися, але залишки суміші все ще можуть бути небезпечними.\n\nВикористовуй лише видану посудину. Не торкайся матеріалу руками й не змішуй залишки з різних чаш.\n\nПотрібен один зразок із місця, де ще видно слабке світіння. Щойно посудина наповниться, одразу закрий кришку.', 'Із ритуальної чаші зібрано та запечатано один зразок невідомого матеріалу.', 87, 3.23, {'reward_formula': None, 'quest_item': {'item_key': 'dark_forest_ritual_ash_sample', 'display_name': 'Проба ритуального попелу', 'quantity': 1, 'drop_chance': 0.15, 'drop_location_id': 'dark_forest', 'drop_message': '🧩 Сюжетна знахідка: Проба ритуального попелу'}, 'progress_text': 'Пошук зразка з ритуальної чаші: {progress}/1', 'item_reveal_policy': {'pre_reveal_title': 'Залишки обряду', 'post_reveal_title': 'Залишки обряду', 'reveal_on_first_drop': True}, 'first_drop_text': 'У чаші знайдено чорний попіл із дрібними синюватими крупинками. Матеріал зібрано в захисну посудину й запечатано.', 'next_route': {'npc_id': 'alchemist', 'route_text': '🏙️ Місто → ⚒️ Ремісничий квартал → 🧪 Алхімік'}}),
    V2StoryQuestContentRecord('dark_forest_079_price_of_the_ritual', 79, 'Ціна обряду', 'TURN_IN', 'dark_forest', 8, 'dark_forest_078_remnants_of_the_ritual', 'alchemist', 'alchemist', 1, 'Передати Алхіміку запечатану пробу для визначення матеріалів, використаних під час обряду.', 'Передати Алхіміку пробу ритуального попелу.', 'Постав посудину в захисну камеру. Я нагрію лише невелику частину проби й простежу за реакцією крупинок.\n\nТут є залишки деревної смоли, крові та рунічного кристала. Але основний компонент значно небезпечніший.\n\nУ попелі містяться сліди кісткового порошку й тканин істот, змінених рунічною корупцією. Під час обряду з них витягували енергію, а потім накопичували її в підготовлених амулетах.\n\nТепер зрозуміло, як підсилювали Ватажка та гоблінських берсерків. Але ця суміш надто складна, щоб гобліни могли створити її самостійно.', 'Алхімік приймає пробу й підтверджує, що під час обряду рунічну силу витягували з істот, змінених корупцією.', 87, 3.23, {'reward_formula': None, 'required_quest_items': [{'item_key': 'dark_forest_ritual_ash_sample', 'quantity': 1, 'consume': True}], 'next_route': {'npc_id': 'elder', 'route_text': '🏙️ Місто → 🏛️ Ратуша → 🗣️ Староста'}}),
    V2StoryQuestContentRecord('dark_forest_080_trace_of_the_runic_cult', 80, 'Слід рунічного культу', 'TURN_IN', 'dark_forest', 8, 'dark_forest_079_price_of_the_ritual', 'elder', 'elder', 1, 'Доповісти Старості про сьому стоянку, рунічні знаки та спосіб підсилення гоблінів.', 'Доповісти Старості про результати розслідування сьомої стоянки.', 'Тепер усі знахідки складаються в одну картину.\n\nСьома стоянка була місцем обрядів. Там готували амулети, підсилювали гоблінів і витягували рунічну енергію з істот, змінених корупцією.\n\nВатажок із Початку Шляху був лише одним із носіїв. Гоблінські командири також не є справжнім джерелом загрози.\n\nХтось навчив гоблінів проводити обряди, постачає їм рунічні матеріали та контролює мережу таборів. Це не випадкові досліди окремого шамана, а організована діяльність.\n\nВідтепер ми вважатимемо цю невідому групу рунічним культом, доки не встановимо, хто саме до неї входить.', 'Староста приймає доповідь про сьому стоянку.\n\nЗібрані докази підтверджують, що рунічна корупція поширюється навмисно. Амулети, підсилення Ватажка та обряди в Темному Борі пов’язані між собою.\n\n✅ Розділ «Слід рунічного культу» завершено.', 87, 3.23, {'reward_formula': None, 'required_quest_items': [], 'itemless_turn_in_policy': {'enabled': True, 'purpose': 'final_report', 'button_text': '🗣️ Доповісти Старості'}}),
)

def validate_story_dark_forest_71_80() -> None:
    quests=STORY_DARK_FOREST_71_80
    if len(quests)!=10 or [q.number for q in quests]!=list(range(71,81)): raise ValueError('invalid_package_identity')
    if len({q.quest_id for q in quests})!=10: raise ValueError('duplicate_quest_id')
    if quests[0].previous_quest_id!='dark_forest_070_seventh_camp': raise ValueError('invalid_story_bridge')
    for previous,current in zip(quests,quests[1:]):
        if current.previous_quest_id!=previous.quest_id: raise ValueError('invalid_predecessor_chain')
    for quest in quests:
        if quest.unlock_level!=8 or quest.location_id!='dark_forest': raise ValueError('invalid_level_or_location')
        if quest.reward_exp < 0 or quest.reward_gold < 0: raise ValueError('invalid_reward')

validate_story_dark_forest_71_80()
